style.css:
@-moz-document domain("discord.com") {
/* Main app container background setup */
    [class*="appMount_"], 
    [class*="app_"], 
    [class*="bg_"], 
    body {
        background-image: url('https://i.imgur.com/8dN7AiK.jpeg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    /* Make all major layout panels fully transparent */
    [class*="layer_"],
    [class*="container_"],
    [class*="sidebar_"],
    [class*="chat_"],
    [class*="chatContent_"],
    [class*="guilds_"],
    [class*="scroller_"],
    [class*="privateChannels_"],
    [class*="panels_"],
    [class*="members_"],
    [class*="pageWrapper_"],
    [class*="standardSidebarView_"],
    [class*="contentRegion_"],
    [class*="sidebarRegion_"] {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* Add a slight translucent backdrop to text chat for readability */
    [class*="chatContent_"] {
        background: rgba(0, 0, 0, 0.4) !important;
    }

    /* Clean up borders and divider lines that block the image */
    [class*="searchBar_"],
    [class*="header_"],
    [class*="container_"]::after {
        box-shadow: none !important;
        border: none !important;
    }
}
